module.exports=[19065,a=>{"use strict";let b=(0,a.i(25246).registerClientReference)(function(){throw Error("Attempted to call BandeauDevlog() from the server but BandeauDevlog is on the client. It's not possible to invoke a client function from the server, it can only be rendered as a Component or passed to props of a Client Component.")},"[project]/apps/web/src/app/(app)/bandeau-devlog.tsx","BandeauDevlog");a.s(["BandeauDevlog",0,b])},69368,a=>{"use strict";var b=a.i(19065);a.n(b)},78956,a=>{"use strict";var b=a.i(43119);function c(a){return a.replace(/ ([!?:;%»])/g," $1").replace(/« /g,"« ")}let d=[{version:"0.14",date:"2026-11-10",titre:"Ce soir d'un coup d'œil, et Foox sur ton écran d'accueil",points:["En tête des Analyses, une bande « Ce soir » — ou « Ce week-end » — rassemble les affiches de tes championnats, toutes compétitions confondues. Touche une affiche pour ouvrir sa fiche.","Au Vestiaire, « Foox en appli » : un bouton pour installer Foox sur ton téléphone, ou la marche à suivre sur iPhone.","Au Classement, tu vois ton vrai rang, même au-delà de la cinquantième place — et dans la course de la semaine aussi.","Nouvelle règle : les points d'un prono sont ceux du moment où tu choisis ton vainqueur. Changer le score sans changer de vainqueur garde tes points ; changer de vainqueur les recalcule. Tes pronos déjà posés ne bougent pas."]},{version:"0.13",date:"2026-11-10",titre:"L'heure juste, et des pronos qui ne se perdent plus",points:["Les heures de match sont à l'heure de Bruxelles : un coup d'envoi à 20 h 45 s'affiche 20 h 45, et non plus une ou deux heures trop tôt.","Un prono qui ne part pas te dit pourquoi — pas de réseau, session expirée, match verrouillé — et ne saute plus le match.","L'onglet Pronos s'ouvre là où il te reste des pronos, et chaque drapeau dit combien il en reste. « En cours » montre tout de suite le prono que tu viens de poser.","« Ta saison » compte toute ta saison. La course de la semaine et l'XP comptent enfin les bonus du score exact et des 2,5 buts : ton XP a pu monter d'un coup.","Un lien d'invitation de groupe ouvert sans être connecté te ramène au groupe après la connexion.","Au Vestiaire, « Mon compte » : changer ton mot de passe, exporter tes données, supprimer ton compte. Et un groupe se quitte — ou se supprime, si c'est toi qui l'as créé.","Des textes plus lisibles, des pages d'erreur en français, et la page « Comprendre » relue."]},{version:"0.12",date:"2026-11-05",titre:"Les coupes entrent dans Foox",points:["Ligue des champions, Ligue Europa et Ligue Conférence sont là, en entier, sous le drapeau Europe — en analyse comme en prono.","Les coupes nationales apparaissent quand un club de nos dix championnats les joue.","Sur un match de coupe, le pourcentage est l'opinion collective des parieurs, marge retirée : notre modèle ne sait pas encore comparer deux championnats. C'est écrit sur chaque fiche.","Le bilan des coupes est tenu à part : le mêler à celui de notre modèle serait malhonnête."]},{version:"0.11",date:"2026-08-31",titre:"Une porte d'entrée",points:["À chaque ouverture, un écran d'accueil : les drapeaux des championnats, un compteur qui file à 100 %, puis le renard en écusson.","« Continuer » ouvre l'app. Juste dessous, le rappel : Foox n'est pas un site de jeux d'argent — aucune mise, aucun gain d'argent.","Installée sur ton téléphone, l'app affiche cet écran tout de suite, pendant que le reste charge.","Et un slogan : « Le hasard a des habitudes »."]},{version:"0.10",date:"2026-08-22",titre:"Les pronos, version 3",points:["L'écran de prono va à l'essentiel : la carte du match donne les pourcentages et les points de chaque issue, tu règles ton score, puis Valider ou Passer.","En bas, l'analyse du renard : les 6 scores les plus probables, son favori en tête — un tap et il se met en place.","Un carrousel de drapeaux filtre les trois onglets — À faire, En cours, Passés — et ton choix te suit de l'un à l'autre.","En cours : chaque prono tient sur une carte compacte — ton score, l'avis du renard, un crayon pour modifier.","Passés : la carte pulse en vert quand ton prono rapporte, en rouge quand il tombe. Et si tu avais posé le score favori du renard et qu'il est tombé, il sort la couronne.","Les défis du jour se feuillettent aux flèches : un défi à la fois, avec l'XP à prendre.","Les combos quittent l'app : chaque prono compte désormais seul."]},{version:"0.9",date:"2026-08-18",titre:"La préférence du renard",points:["Le renard ne suit plus bêtement le plus gros pourcentage : chaque issue est comparée à ce qu'elle vaut d'habitude dans le foot — et quand un match nul est exceptionnel, il ose le préférer. Son bilan public le juge là-dessus, erreurs comprises.","L'écran de prono retrouve l'ordre d'un parieur : l'analyse du match (1 X 2), LA prédiction du renard, son sentiment — Peureux, Prudent ou Confiant — puis ton score. En bas, les trois scores les plus probables, en pourcentages, un tap et c'est prérempli.","Un « Pourquoi ? » ouvre une nouvelle page : comprendre les pourcentages, avec les vrais chiffres — ce qui arrive vraiment à domicile, à l'extérieur, et pourquoi un nul à 32 % vaut plus qu'une victoire à 35 %."]},{version:"0.8",date:"2026-08-18",titre:"Prudent, neutre ou risqué ?",points:["Avant chaque prono, le renard te souffle trois scores : le prudent, le neutre et le risqué — chacun avec les points qu'il peut rapporter. Un tap et il se met en place, tu restes libre de le retoucher.","Sur la fiche d'analyse, les trois scénarios s'affichent avec leurs chances : la lecture du renard ne se résume plus à un seul score.","Les coups d'envoi sont maintenant vérifiés chaque nuit auprès d'une source qui suit les vrais horaires : fini les matchs affichés au mauvais jour quand le calendrier bouge."]},{version:"0.7",date:"2026-08-17",titre:"Ton foot d'abord",points:["À ta prochaine visite, l'app te demande TES championnats et ton club de cœur — deux gestes, et ton accueil devient le tien : le prochain match de ton club passe en tête.","Tu changes d'avis quand tu veux : dans le Vestiaire, ton club de cœur a sa carte, avec « Changer » juste à côté.","Tes points tombent la nuit même du match, plus le surlendemain : les scores arrivent dans l'app quelques heures après le coup de sifflet final.","Les maillots néerlandais et belges retrouvent leurs couleurs : les médaillons gris d'Eredivisie et de Pro League passent aux couleurs officielles des clubs."]},{version:"0.6",date:"2026-08-16",titre:"L'accueil respire",points:["L'accueil est refait : le match à l'affiche, ton bouton pronos juste dessous, puis les défis et la course en une ligne chacun — fini l'écran surchargé.","Le renard a un nouveau tour : l'anneau autour de sa tête se vide en 5 secondes, et quand il est à sec, sa remarque suivante arrive. Tape-le pour aller plus vite.","Partout, les boutons parlent en mots courts — les phrases restent au renard et à l'analyse.","Les numéros d'aide du bas de page ont été vérifiés un à un — et le lien belge, qui était cassé, est réparé (0800 35 777, 24 h/24).","Le menu du bas change : « Matchs » devient « Accueil », l'onglet Pronos fait son entrée, et Analyses brille en doré — c'est l'étage premium.","Les Analyses suivent : boutons partout, compteurs compacts, puce sablier sur les matchs à venir — et l'avis du renard, lui, garde ses mots.","Ton prono démarre à 0-0 : chaque but est un geste à toi, plus un pré-rempli à corriger."]},{version:"0.5",date:"2026-08-16",titre:"Les résultats arrivent",points:["Les matchs terminés affichent leur score, et tes points tombent le lendemain matin — c'est écrit noir sur blanc sur tes pronos en cours.","Dans Analyses, tu peux remonter les jours passés : ce que le renard voyait avant le match, et ce qui est réellement arrivé.","Réparé : les résultats n'entraient plus depuis le 12 août — tout est à jour.","Et un bandeau tout en haut : la version de l'app, sa date, et ce « Quoi de neuf ? » que tu es en train de lire."]},{version:"0.4",date:"2026-08-15",titre:"Le score exact, et un renard mieux réglé",points:["Ton prono devient un score exact : un seul geste, trois façons de marquer des points.","La lecture du renard s'affiche en 3 cartes cohérentes : résultat, score exact, buts.","Le renard a été réglé au plus juste après avoir rejoué toute la saison dernière — championnat par championnat.","Le catalogue est complet : Espagne, Italie, Pays-Bas, Portugal, Écosse et Turquie rejoignent les 10 championnats suivis.","Nouveaux avatars : le renard a retrouvé une vraie tête de renard.","Le Centre de formation quitte l'app — on se concentre sur l'analyse et le jeu."]},{version:"0.3",date:"2026-08-13",titre:"La grande refonte",points:["La fiche match ouvre sur « La lecture du renard » : l'avis d'abord, la preuve ensuite pour qui veut creuser.","Les clubs portent leurs vraies couleurs en médaillons, partout dans l'app.","Les défis du jour : une petite route quotidienne, et le tour des mots.","Les classements par championnat arrivent, et la Bundesliga entre au catalogue."]},{version:"0.2",date:"2026-08-12",titre:"Les combos et la fiche match",points:["Les combos : 2 à 5 pronos qui passent ou tombent ensemble.","La fiche match explique chaque chiffre — et chaque analyse est scellée le jour même, échecs compris.","Tes pronos se rangent en trois onglets : à faire, en cours, passés."]},{version:"0.1",date:"2026-08-11",titre:"La naissance de la bêta",points:["Premiers pronos sur la Premier League et la Ligue 1.","64 renards en pixel art — choisis le tien au Vestiaire.","Les groupes entre amis, avec une invitation en un lien."]}];function e(a){return{...a,titre:c(a.titre),points:a.points.map(c)}}let f=e(d[0]),g=d.map(e);a.s(["w",0,f,"u",0,g,"C",0,function(a){return new Intl.DateTimeFormat("fr-FR",{day:"numeric",month:"long",timeZone:b.f}).format(new Date(a))}])}];

